#include <vector>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
  int xor_int = 0; // use int because OpenMP reductions are well-defined for int
#pragma omp parallel for reduction(^ : xor_int)
  for (std::size_t i = 0; i < x.size(); ++i) {
    xor_int ^= static_cast<int>(x[i]);
  }
  return xor_int != 0;
}
